/**
 * Writes supabase/seed.sql from the shared simulated catalogue so the
 * database, the API and the apps all agree on the same inventory.
 *   npm run db:seed-sql
 */
import { writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { OFFERS, PRODUCTS, STORES } from '../src/seed';

const q = (v: string) => `'${v.replace(/'/g, "''")}'`;
const arr = (xs: string[]) => `array[${xs.map(q).join(', ')}]::text[]`;

const lines: string[] = [
  '-- Generated by packages/shared/scripts/seed-sql.ts. Do not edit by hand.',
  '-- Simulated inventory: no store here is connected to GET.',
  'begin;',
  'delete from public.offers; delete from public.products; delete from public.stores;',
];

for (const s of STORES) {
  lines.push(
    `insert into public.stores (id, name, kind, category, address, city, country, currency, lat, lng, rating, verified, has_pickup, has_delivery, delivery_radius_km, ships_international, prep_minutes, hours) values (${[
      q(s.id), q(s.name), q(s.kind), q(s.category), q(s.address), q(s.city), q(s.country), q(s.currency),
      s.lat, s.lng, s.rating, s.verified, s.hasPickup, s.hasDelivery, s.deliveryRadiusKm, s.shipsInternational, s.prepMinutes, q(s.hours),
    ].join(', ')});`,
  );
}
for (const p of PRODUCTS) {
  lines.push(
    `insert into public.products (id, name, brand, category, description, tags, glyph, base_price_usd, requirements, is_service) values (${[
      q(p.id), q(p.name), q(p.brand), q(p.category), q(p.description), arr(p.tags), q(p.glyph), p.basePriceUSD, arr(p.requirements), p.isService,
    ].join(', ')});`,
  );
}
for (const o of OFFERS) {
  lines.push(
    `insert into public.offers (id, product_id, store_id, price, stock, inventory_verified, modes, delivery_fee) values (${[
      q(o.id), q(o.productId), q(o.storeId), o.price, o.stock, o.inventoryVerified, `array[${o.modes.map(q).join(', ')}]::public.fulfilment_mode[]`, o.deliveryFee,
    ].join(', ')});`,
  );
}
lines.push('commit;', '');

const out = resolve(dirname(fileURLToPath(import.meta.url)), '../../../supabase/seed.sql');
writeFileSync(out, lines.join('\n'));
console.log(`Wrote ${STORES.length} stores, ${PRODUCTS.length} products, ${OFFERS.length} offers to ${out}`);
